// Split uploaded PDF files into separate items
// The webapp sends files as FormData with keys 'file1', 'file2'
const items = [];
const inputItem = $input.first();
const binary = inputItem.binary;

if (!binary || Object.keys(binary).length === 0) {
  throw new Error('No PDF files received. Please upload at least one PDF.');
}

for (const [key, binaryData] of Object.entries(binary)) {
  items.push({
    json: {
      fileKey: key,
      fileName: binaryData.fileName || key
    },
    binary: {
      data: binaryData
    }
  });
}

return items;

// Parse extracted PDF text into structured JSON
// Extracts all 'Key: Value' pairs from the PDF text
const results = [];

for (const item of $input.all()) {
  const text = item.json.text || '';
  const parsed = {};

  const lines = text.split('\n');
  let currentKey = null;

  for (let i = 0; i < lines.length; i++) {
    const trimmed = lines[i].trim();
    if (!trimmed) {
      currentKey = null;
      continue;
    }

    // Find first colon to split Key: Value
    const colonIdx = trimmed.indexOf(':');

    if (colonIdx > 0) {
      const key = trimmed.substring(0, colonIdx).trim().replace(/\s+/g, ' ');
      const value = trimmed.substring(colonIdx + 1).trim();

      // Only accept reasonable key lengths (skip URLs, timestamps etc)
      if (key.length > 0 && key.length < 80) {
        parsed[key] = value;
        currentKey = key;
      }
    } else if (currentKey && parsed[currentKey] !== undefined) {
      // Continuation line - append to previous value
      parsed[currentKey] += ' ' + trimmed;
    }
  }

  results.push(parsed);
}

// Return as { results: [...] } so the webapp can display each PDF separately
return [{ json: { results } }];
